import { BiomeId, BlockId } from "./blocks";
import { VoxelWorld } from "./voxelWorld";
import type { WorldType } from "./worldTypes";

/**
 * Deterministic terrain generation.
 *
 * ⚠ Saves store only the seed plus block-change deltas, so generateWorld() must
 * produce byte-identical output for a given seed forever. Generation order, the
 * PRNG, the noise functions, and every constant below are part of the save
 * format. generation.test.ts pins the output with SHA-256 digests — if it fails
 * after a change here, the change breaks existing saves.
 */

/**
 * Every value here is part of the save format (see module header). Names exist
 * for readability; changing a value re-rolls every world.
 */
export const GEN = Object.freeze({
  seaLevel: 43,
  borderWallHeight: 14,
  biomes: Object.freeze({
    [BiomeId.Plains]: Object.freeze({ baseHeight: 47, noiseScale: 2.0, treeChance: 0.18 }),
    [BiomeId.Desert]: Object.freeze({ baseHeight: 46, noiseScale: 3.5, treeChance: 0.01 }),
    [BiomeId.Ocean]: Object.freeze({ baseHeight: 30, noiseScale: 2.5, treeChance: 0 }),
    [BiomeId.Forest]: Object.freeze({ baseHeight: 50, noiseScale: 4.0, treeChance: 0.6 }),
    [BiomeId.Mountains]: Object.freeze({ baseHeight: 55, noiseScale: 18.0, treeChance: 0.05 })
  }),
  mountainStoneAboveY: 65,
  snowAboveY: 68,
  // Lava pools in the deepest caves: carved air at or below this Y floods with
  // lava, well under the surface so it stays a deep-cave hazard.
  lavaLevel: 9,
  // Sand shoreline band around sea level (deeper floors keep their biome top).
  beachMaxAboveSea: 1,
  beachDepthBelowSea: 2,
  caveCount: 230,
  caveChamberCount: 150,
  treeAttempts: 9000,
  // Cacti per dry desert column — keyed on area so drowned deserts get few.
  cactusChance: 0.012,
  houseCount: 120,
  dungeonCount: 28,
  // Villages: clusters of houses (reusing placeHouse) on flat, dry land, placed on
  // their own decoupled PRNG (villageRand) so they never shift the shared stream.
  // Each valid site seeds a small resident villager population at boot.
  villageCount: 12,
  villageHouseCount: 5,
  villagersPerVillage: 4,
  villageMinSpawnDistance: 30,
  // A village only lands where the seed-pure surface across its footprint stays
  // within this many blocks (so it sits on flat plains/desert, not a mountainside);
  // a small terrace then levels the rest, keeping the build natural-looking.
  villageFlatnessTolerance: 2,
  oreConfigs: Object.freeze([
    { id: BlockId.SliverOre, attempts: 120000, minY: 3, maxYOffset: 10, minSize: 3, maxSize: 10 },
    { id: BlockId.RubyOre, attempts: 52000, minY: 2, maxYOffset: 16, minSize: 3, maxSize: 10 },
    { id: BlockId.GoldOre, attempts: 36000, minY: 2, maxYOffset: 22, minSize: 3, maxSize: 10 },
    { id: BlockId.SapphireOre, attempts: 28000, minY: 2, maxYOffset: 28, minSize: 2, maxSize: 7 },
    { id: BlockId.DiamondOre, attempts: 18000, minY: 2, maxYOffset: 36, minSize: 2, maxSize: 6 }
  ]),
  // Coal is placed in its own pass on a dedicated PRNG (see placeCoal) so it never
  // shifts the shared `rand` stream — existing ores, trees, and structures stay
  // byte-identical to before coal, exactly as deep-cave lava did. It is the
  // shallowest, most common ore: large veins reaching near the surface.
  coalConfig: Object.freeze({ attempts: 160000, minY: 4, maxYOffset: 8, minSize: 4, maxSize: 12 })
});

/**
 * The terrain-shaping subset of GEN that a world type can vary: sea level and
 * per-biome surface height (base + noise amplitude). Everything else (caves,
 * ores, lava, trees, structures, dungeons) is type-independent and still reads
 * GEN directly. `terrainConfigFor("default")` returns exactly the GEN values, so
 * the default world stays byte-identical.
 */
export type TerrainConfig = {
  seaLevel: number;
  biomes: Record<BiomeId, { baseHeight: number; noiseScale: number }>;
};

const BIOME_IDS = [BiomeId.Plains, BiomeId.Desert, BiomeId.Ocean, BiomeId.Forest, BiomeId.Mountains] as const;

/** Builds a biome height table from GEN, applying `transform` to each biome's base/scale. */
function biomeHeights(
  transform: (b: { baseHeight: number; noiseScale: number }, id: BiomeId) => { baseHeight: number; noiseScale: number }
): Record<BiomeId, { baseHeight: number; noiseScale: number }> {
  const out = {} as Record<BiomeId, { baseHeight: number; noiseScale: number }>;
  for (const id of BIOME_IDS) {
    const g = GEN.biomes[id];
    out[id] = transform({ baseHeight: g.baseHeight, noiseScale: g.noiseScale }, id);
  }
  return out;
}

// A raised sea with land biomes lifted so they break the surface as gently
// sloped islands (gentle enough that findSpawnOnLand still finds a dry spawn),
// while oceans stay as deep channels between them.
const ISLANDS_BIOMES: Record<BiomeId, { baseHeight: number; noiseScale: number }> = {
  [BiomeId.Plains]: { baseHeight: 54, noiseScale: 4 },
  [BiomeId.Desert]: { baseHeight: 52, noiseScale: 3 },
  [BiomeId.Ocean]: { baseHeight: 34, noiseScale: 3 },
  [BiomeId.Forest]: { baseHeight: 56, noiseScale: 5 },
  [BiomeId.Mountains]: { baseHeight: 64, noiseScale: 16 }
};

/** The terrain config for a world type. "default" returns the GEN values verbatim. */
export function terrainConfigFor(worldType: WorldType): TerrainConfig {
  switch (worldType) {
    case "flat":
      // Flat dry ground just above sea level (no water); biome-colored top.
      return { seaLevel: GEN.seaLevel, biomes: biomeHeights(() => ({ baseHeight: 48, noiseScale: 0 })) };
    case "amplified":
      // Exaggerated relief; mountains clamp at the height ceiling as plateaus.
      return { seaLevel: GEN.seaLevel, biomes: biomeHeights((b) => ({ baseHeight: b.baseHeight, noiseScale: b.noiseScale * 2 })) };
    case "islands":
      return { seaLevel: 54, biomes: ISLANDS_BIOMES };
    default:
      return { seaLevel: GEN.seaLevel, biomes: biomeHeights((b) => b) };
  }
}

function hash2D(x: number, z: number): number {
  const n = Math.sin(x * 127.1 + z * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

function smoothNoise2D(x: number, z: number, seed: number): number {
  const s = seed * 0.013;
  const val =
    Math.sin(x * 0.015 + s) * 1.2 +
    Math.cos(z * 0.012 + s * 1.4) * 1.2 +
    Math.sin(x * 0.005 - z * 0.007 + s * 0.7) * 3.5 +
    Math.cos(x * 0.031 + z * 0.027 + s * 2.1) * 0.4;
  return val;
}

export function generateWorld(world: VoxelWorld, worldType: WorldType = "default"): void {
  // Fork on the type up front, before any block write: "default" yields the GEN
  // values so its output is byte-identical to before this feature.
  const cfg = terrainConfigFor(worldType);

  const rand = (() => {
    let t = (world.seed >>> 0) + 0x6d2b79f5;
    return () => {
      t += 0x6d2b79f5;
      let r = Math.imul(t ^ (t >>> 15), 1 | t);
      r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
      return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
    };
  })();

  generateTerrain(world, cfg);
  carveCaves(world, rand);
  placeWater(world, cfg);
  placeBeaches(world, cfg);
  placeOres(world, rand);
  // Coal runs on its own PRNG (placeCoal), so it adds ore underground without
  // shifting the shared `rand` — trees/structures/dungeons stay byte-identical.
  placeCoal(world);
  // After placeOres so it can't shift ore RNG (placeOres gates rand on air
  // adjacency, which lava would change), and before placeDungeons so dungeon
  // rooms — whose floors can sit at or below lavaLevel — overwrite any lava
  // rather than flooding. Trees/cacti/houses only read the surface, far above.
  placeLava(world);
  placeTrees(world, rand);
  placeCacti(world);
  placeStructures(world, rand);
  placeDungeons(world, cfg);
  // Villages run LAST on their own decoupled PRNG (villageRand), so they add
  // structures without shifting any other stream — every pass above stays
  // byte-identical to a village-less world of the same seed.
  placeVillages(world, cfg);
}

function generateTerrain(world: VoxelWorld, cfg: TerrainConfig): void {
  const maxX = world.sizeX - 1;
  const maxZ = world.sizeZ - 1;

  // Fast clear and bedrock
  world.blocks.fill(BlockId.Air);
  for (let x = 0; x < world.sizeX; x += 1) {
    for (let z = 0; z < world.sizeZ; z += 1) {
      world.set(x, 0, z, BlockId.Bedrock);
    }
  }

  for (let x = 0; x < world.sizeX; x += 1) {
    for (let z = 0; z < world.sizeZ; z += 1) {
      const biome = world.getBiome(x, z);
      const noise = smoothNoise2D(x, z, world.seed);
      const { baseHeight, noiseScale } = cfg.biomes[biome];

      const topY = Math.max(5, Math.min(world.sizeY - 5, Math.floor(baseHeight + noise * noiseScale)));
      let topBlock = BlockId.Grass;
      if (biome === BiomeId.Desert || biome === BiomeId.Ocean) {
        topBlock = BlockId.Sand;
      } else if (biome === BiomeId.Mountains && topY > GEN.snowAboveY) {
        topBlock = BlockId.Snow;
      } else if (biome === BiomeId.Mountains && topY > GEN.mountainStoneAboveY) {
        topBlock = BlockId.Stone;
      }

      for (let y = 1; y <= topY; y += 1) {
        if (y === topY) {
          world.set(x, y, z, topBlock);
        } else if (y > topY - 3) {
          world.set(x, y, z, topBlock === BlockId.Sand ? BlockId.Sand : BlockId.Dirt);
        } else if (y > topY - 8 && hash2D(x * 0.2 + y * 0.1, z * 0.2) > 0.88) {
          world.set(x, y, z, BlockId.Cobblestone);
        } else {
          world.set(x, y, z, BlockId.Stone);
        }
      }
    }
  }

  // Unbreakable border walls.
  for (let y = 1; y <= GEN.borderWallHeight; y += 1) {
    for (let x = 0; x < world.sizeX; x += 1) {
      world.set(x, y, 0, BlockId.Bedrock);
      world.set(x, y, maxZ, BlockId.Bedrock);
    }
    for (let z = 0; z < world.sizeZ; z += 1) {
      world.set(0, y, z, BlockId.Bedrock);
      world.set(maxX, y, z, BlockId.Bedrock);
    }
  }
}

function carveCaves(world: VoxelWorld, rand: () => number): void {
  const carveSphere = (cx: number, cy: number, cz: number, radius: number) => {
    const r2 = radius * radius;
    const minX = Math.max(1, Math.floor(cx - radius));
    const maxXc = Math.min(world.sizeX - 2, Math.ceil(cx + radius));
    const minY = Math.max(1, Math.floor(cy - radius));
    const maxYc = Math.min(world.sizeY - 2, Math.ceil(cy + radius));
    const minZ = Math.max(1, Math.floor(cz - radius));
    const maxZc = Math.min(world.sizeZ - 2, Math.ceil(cz + radius));
    for (let y = minY; y <= maxYc; y += 1) {
      for (let z = minZ; z <= maxZc; z += 1) {
        for (let x = minX; x <= maxXc; x += 1) {
          const dx = x - cx;
          const dy = y - cy;
          const dz = z - cz;
          if (dx * dx + dy * dy + dz * dz > r2) continue;
          const block = world.get(x, y, z);
          if (block !== BlockId.Bedrock) world.set(x, y, z, BlockId.Air);
        }
      }
    }
  };

  for (let i = 0; i < GEN.caveCount; i += 1) {
    let x = 12 + rand() * (world.sizeX - 24);
    let y = 3 + rand() * (world.sizeY - 9);
    let z = 12 + rand() * (world.sizeZ - 24);
    let yaw = rand() * Math.PI * 2;
    let pitch = (rand() - 0.5) * 0.26;
    const length = 56 + Math.floor(rand() * 56);
    for (let step = 0; step < length; step += 1) {
      const r = 1.9 + rand() * 2.6;
      carveSphere(x, y, z, r);
      if (rand() > 0.968) carveSphere(x, y, z, 4.8 + rand() * 4.6);
      yaw += (rand() - 0.5) * 0.28;
      pitch = Math.max(-0.55, Math.min(0.55, pitch + (rand() - 0.5) * 0.16));
      x += Math.cos(yaw);
      z += Math.sin(yaw);
      y += Math.sin(pitch) * 0.8;
      if (x < 8 || x > world.sizeX - 8 || z < 8 || z > world.sizeZ - 8 || y < 2 || y > world.sizeY - 4) break;
    }
  }

  for (let i = 0; i < GEN.caveChamberCount; i += 1) {
    const cx = 12 + rand() * (world.sizeX - 24);
    const cy = 5 + rand() * (world.sizeY - 14);
    const cz = 12 + rand() * (world.sizeZ - 24);
    carveSphere(cx, cy, cz, 5.4 + rand() * 6.4);
  }
}

function placeLava(world: VoxelWorld): void {
  const { lavaLevel } = GEN;
  for (let x = 1; x < world.sizeX - 1; x += 1) {
    for (let z = 1; z < world.sizeZ - 1; z += 1) {
      for (let y = 1; y <= lavaLevel; y += 1) {
        if (world.get(x, y, z) === BlockId.Air) world.set(x, y, z, BlockId.Lava);
      }
    }
  }
}

function placeWater(world: VoxelWorld, cfg: TerrainConfig): void {
  const { seaLevel } = cfg;
  for (let x = 1; x < world.sizeX - 1; x += 1) {
    for (let z = 1; z < world.sizeZ - 1; z += 1) {
      const topY = world.highestSolidY(x, z);
      if (topY >= seaLevel) continue;
      for (let y = topY + 1; y <= seaLevel; y += 1) {
        if (world.get(x, y, z) === BlockId.Air) world.set(x, y, z, BlockId.Water);
      }
    }
  }
}

function placeOres(world: VoxelWorld, rand: () => number): void {
  const hasNearbyAir = (x: number, y: number, z: number): boolean => {
    return (
      world.get(x + 1, y, z) === BlockId.Air ||
      world.get(x - 1, y, z) === BlockId.Air ||
      world.get(x, y + 1, z) === BlockId.Air ||
      world.get(x, y - 1, z) === BlockId.Air ||
      world.get(x, y, z + 1) === BlockId.Air ||
      world.get(x, y, z - 1) === BlockId.Air ||
      world.get(x + 1, y, z) === BlockId.Water ||
      world.get(x - 1, y, z) === BlockId.Water ||
      world.get(x, y + 1, z) === BlockId.Water ||
      world.get(x, y - 1, z) === BlockId.Water ||
      world.get(x, y, z + 1) === BlockId.Water ||
      world.get(x, y, z - 1) === BlockId.Water
    );
  };

  const placeOreVein = (x: number, y: number, z: number, ore: BlockId, minSize: number, maxSize: number) => {
    const size = minSize + Math.floor(rand() * Math.max(1, maxSize - minSize + 1));
    for (let i = 0; i < size; i += 1) {
      const vx = x + Math.floor((rand() - 0.5) * 4);
      const vy = y + Math.floor((rand() - 0.5) * 3);
      const vz = z + Math.floor((rand() - 0.5) * 4);
      if (!world.inBounds(vx, vy, vz) || vy <= 1) continue;
      const b = world.get(vx, vy, vz);
      if (b === BlockId.Stone || b === BlockId.Cobblestone) world.set(vx, vy, vz, ore);
    }
  };

  for (const config of GEN.oreConfigs) {
    for (let i = 0; i < config.attempts; i += 1) {
      const x = 8 + Math.floor(rand() * (world.sizeX - 16));
      const y = config.minY + Math.floor(rand() * Math.max(2, world.sizeY - config.maxYOffset));
      const z = 8 + Math.floor(rand() * (world.sizeZ - 16));
      const block = world.get(x, y, z);
      if ((block !== BlockId.Stone && block !== BlockId.Cobblestone) || !hasNearbyAir(x, y, z)) continue;
      placeOreVein(x, y, z, config.id, config.minSize, config.maxSize);
    }
  }
}

/** A coal-only PRNG seeded from the world seed, decoupled from the main gen stream. */
function coalRand(seed: number): () => number {
  let t = (seed ^ 0x85ebca6b) >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Coal veins, placed on their own PRNG so the pass never consumes from the shared
 * `rand` stream — every other ore, tree, and structure stays byte-identical to a
 * coal-free world. Like the other ores, coal only replaces stone/cobblestone.
 */
function placeCoal(world: VoxelWorld): void {
  const rand = coalRand(world.seed);
  const cfg = GEN.coalConfig;
  const placeVein = (x: number, y: number, z: number) => {
    const size = cfg.minSize + Math.floor(rand() * Math.max(1, cfg.maxSize - cfg.minSize + 1));
    for (let i = 0; i < size; i += 1) {
      const vx = x + Math.floor((rand() - 0.5) * 4);
      const vy = y + Math.floor((rand() - 0.5) * 3);
      const vz = z + Math.floor((rand() - 0.5) * 4);
      if (!world.inBounds(vx, vy, vz) || vy <= 1) continue;
      const b = world.get(vx, vy, vz);
      if (b === BlockId.Stone || b === BlockId.Cobblestone) world.set(vx, vy, vz, BlockId.CoalOre);
    }
  };
  for (let i = 0; i < cfg.attempts; i += 1) {
    const x = 8 + Math.floor(rand() * (world.sizeX - 16));
    const y = cfg.minY + Math.floor(rand() * Math.max(2, world.sizeY - cfg.maxYOffset));
    const z = 8 + Math.floor(rand() * (world.sizeZ - 16));
    const block = world.get(x, y, z);
    if (block !== BlockId.Stone && block !== BlockId.Cobblestone) continue;
    placeVein(x, y, z);
  }
}

/**
 * Sand shorelines: grass columns in the sea-level band turn to beach only
 * when water actually sits nearby — inland basins at sea level stay grass.
 * Runs after placeWater so adjacency can test real water blocks.
 */
function placeBeaches(world: VoxelWorld, cfg: TerrainConfig): void {
  const { seaLevel } = cfg;
  for (let x = 1; x < world.sizeX - 1; x += 1) {
    for (let z = 1; z < world.sizeZ - 1; z += 1) {
      const topY = world.highestSolidY(x, z);
      if (topY > seaLevel + GEN.beachMaxAboveSea || topY < seaLevel - GEN.beachDepthBelowSea) continue;
      if (world.get(x, topY, z) !== BlockId.Grass) continue;

      let nearWater = false;
      for (let dx = -2; dx <= 2 && !nearWater; dx += 1) {
        for (let dz = -2; dz <= 2 && !nearWater; dz += 1) {
          if (world.get(x + dx, seaLevel, z + dz) === BlockId.Water) nearWater = true;
        }
      }
      if (!nearWater) continue;

      for (let y = Math.max(1, topY - 2); y <= topY; y += 1) world.set(x, y, z, BlockId.Sand);
    }
  }
}

function placeTrees(world: VoxelWorld, rand: () => number): void {
  for (let i = 0; i < GEN.treeAttempts; i += 1) {
    const x = 4 + Math.floor(rand() * (world.sizeX - 8));
    const z = 4 + Math.floor(rand() * (world.sizeZ - 8));

    const biome = world.getBiome(x, z);
    const spawnChance = GEN.biomes[biome].treeChance;

    if (rand() > spawnChance) continue;

    const topY = world.highestSolidY(x, z);
    if (world.get(x, topY, z) !== BlockId.Grass) continue;

    const trunkHeight = spawnChance > 0.5 ? 4 + Math.floor(rand() * 3) : 3 + Math.floor(rand() * 3);
    for (let y = 1; y <= trunkHeight; y += 1) world.set(x, topY + y, z, BlockId.Wood);

    const leafStart = topY + trunkHeight - 1;
    for (let ox = -2; ox <= 2; ox += 1) {
      for (let oz = -2; oz <= 2; oz += 1) {
        for (let oy = 0; oy <= 2; oy += 1) {
          const d = Math.abs(ox) + Math.abs(oz) + oy;
          if (d > 4) continue;
          // Only fill air: the canopy must not eat the trunk or neighbors.
          if (world.get(x + ox, leafStart + oy, z + oz) !== BlockId.Air) continue;
          world.set(x + ox, leafStart + oy, z + oz, BlockId.Leaves);
        }
      }
    }
  }
}

function placeCacti(world: VoxelWorld): void {
  // Hash-gated scan instead of random attempts: density follows the dry
  // desert area, so a mostly-flooded desert gets few cacti instead of the
  // whole budget missing. Doesn't consume the shared rand stream.
  for (let x = 4; x < world.sizeX - 4; x += 1) {
    for (let z = 4; z < world.sizeZ - 4; z += 1) {
      if (hash2D(x * 1.7 + 11.3, z * 2.3 - 7.1) > GEN.cactusChance) continue;
      if (world.getBiome(x, z) !== BiomeId.Desert) continue;

      const topY = world.highestSolidY(x, z);
      if (world.get(x, topY, z) !== BlockId.Sand) continue;
      if (world.get(x, topY + 1, z) !== BlockId.Air) continue;

      const height = 2 + (hash2D(z * 3.1, x * 1.3) > 0.5 ? 1 : 0);
      for (let y = 1; y <= height; y += 1) world.set(x, topY + y, z, BlockId.Cactus);
    }
  }
}

function placeStructures(world: VoxelWorld, rand: () => number): void {
  for (let i = 0; i < GEN.houseCount; i += 1) {
    const cx = 12 + Math.floor(rand() * (world.sizeX - 24));
    const cz = 12 + Math.floor(rand() * (world.sizeZ - 24));
    placeHouse(world, cx, cz);
  }
}

function placeHouse(world: VoxelWorld, cx: number, cz: number): void {
  const half = 3;
  const floorY = world.highestSolidY(cx, cz) + 1;
  if (floorY < 3 || floorY + 6 >= world.sizeY - 1) return;

  for (let x = cx - half - 1; x <= cx + half + 1; x += 1) {
    for (let z = cz - half - 1; z <= cz + half + 1; z += 1) {
      if (!world.inBounds(x, floorY - 1, z)) return;
      const y = world.highestSolidY(x, z);
      if (Math.abs(y - (floorY - 1)) > 1) return;
    }
  }

  buildHouseShell(world, cx, cz, floorY);
}

/**
 * Builds the house itself at a pre-validated `floorY` (cobblestone floor pad,
 * brick walls with glass windows, wood corner posts, a door gap, and a plank
 * roof). Split out of placeHouse so villages can level a pad and build on it.
 */
function buildHouseShell(world: VoxelWorld, cx: number, cz: number, floorY: number): void {
  const half = 3;
  for (let x = cx - half; x <= cx + half; x += 1) {
    for (let z = cz - half; z <= cz + half; z += 1) world.set(x, floorY - 1, z, BlockId.Cobblestone);
  }

  for (let y = floorY; y <= floorY + 3; y += 1) {
    for (let x = cx - half; x <= cx + half; x += 1) {
      for (let z = cz - half; z <= cz + half; z += 1) {
        const wall = x === cx - half || x === cx + half || z === cz - half || z === cz + half;
        if (!wall) continue;
        const isWindow = y === floorY + 1 && ((x === cx && (z === cz - half || z === cz + half)) || (z === cz && (x === cx - half || x === cx + half)));
        world.set(x, y, z, isWindow ? BlockId.Glass : BlockId.Brick);
      }
    }
  }

  world.set(cx, floorY + 1, cz - half, BlockId.Air);
  world.set(cx, floorY + 2, cz - half, BlockId.Air);

  for (let y = floorY; y <= floorY + 3; y += 1) {
    world.set(cx - half, y, cz - half, BlockId.Wood);
    world.set(cx + half, y, cz - half, BlockId.Wood);
    world.set(cx - half, y, cz + half, BlockId.Wood);
    world.set(cx + half, y, cz + half, BlockId.Wood);
  }

  for (let x = cx - half - 1; x <= cx + half + 1; x += 1) {
    for (let z = cz - half - 1; z <= cz + half + 1; z += 1) world.set(x, floorY + 4, z, BlockId.Planks);
  }
}

// ── Dungeons ──────────────────────────────────────────────────────────────
// Small underground cobblestone rooms with pre-fillable loot chests and a mob
// spawner. The chest CONTENTS are not generated here (the block-diff save can't
// carry worldgen-placed entities), only the blocks — the engine fills chests
// lazily on first open. To support that, the engine re-derives the chest and
// spawner voxel indices on load via collectDungeonSites(), which replays this
// exact placement math. Two invariants keep build and derive in lockstep:
//   1. A dedicated PRNG seeded only from world.seed (independent of the shared
//      generation stream), and every dungeon draws a fixed number of values up
//      front so the stream stays aligned whether or not the dungeon is placed.
//   2. Placement validates against terrainTopY() — a seed-pure surface estimate
//      — never highestSolidY(), which a cave or a player edit could shift.

type DungeonSink = { chest: (idx: number) => void; spawner: (idx: number) => void };

const NOOP_DUNGEON_SINK: DungeonSink = { chest: () => {}, spawner: () => {} };

/** A PRNG seeded only from the world seed, decoupled from the main gen stream. */
function dungeonRand(seed: number): () => number {
  let t = (seed ^ 0x9e3779b9) >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The generation-time terrain surface at (x,z), computed purely from the seed
 * (mirrors the topY math in generateTerrain). Unlike highestSolidY it reads no
 * blocks, so it is identical at generation and at load — the property that lets
 * collectDungeonSites reproduce the exact dungeon layout.
 */
function terrainTopY(world: VoxelWorld, x: number, z: number, cfg: TerrainConfig): number {
  const biome = world.getBiome(x, z);
  const noise = smoothNoise2D(x, z, world.seed);
  const { baseHeight, noiseScale } = cfg.biomes[biome];
  return Math.max(5, Math.min(world.sizeY - 5, Math.floor(baseHeight + noise * noiseScale)));
}

function buildDungeonRoom(world: VoxelWorld, cx: number, cz: number, floorY: number, secondChest: boolean, write: boolean, sink: DungeonSink): void {
  const half = 3; // 7x7 outer, 5x5x4 hollow interior
  if (write) {
    for (let y = floorY - 1; y <= floorY + 4; y += 1) {
      for (let x = cx - half; x <= cx + half; x += 1) {
        for (let z = cz - half; z <= cz + half; z += 1) {
          if (!world.inBounds(x, y, z)) continue;
          const interior = x > cx - half && x < cx + half && z > cz - half && z < cz + half && y >= floorY && y <= floorY + 3;
          if (interior) {
            world.set(x, y, z, BlockId.Air);
          } else {
            const mossy = hash2D(x * 1.7 + y * 0.9, z * 2.3 - y * 0.6) > 0.6;
            world.set(x, y, z, mossy ? BlockId.MossyCobblestone : BlockId.Cobblestone);
          }
        }
      }
    }
    world.set(cx - 2, floorY, cz - 2, BlockId.Chest);
    if (secondChest) world.set(cx + 2, floorY, cz + 2, BlockId.Chest);
    world.set(cx, floorY, cz, BlockId.Spawner);
  }
  sink.chest(world.index(cx - 2, floorY, cz - 2));
  if (secondChest) sink.chest(world.index(cx + 2, floorY, cz + 2));
  sink.spawner(world.index(cx, floorY, cz));
}

function buildDungeons(world: VoxelWorld, write: boolean, sink: DungeonSink, cfg: TerrainConfig): void {
  const rand = dungeonRand(world.seed);
  const centerX = world.sizeX / 2;
  const centerZ = world.sizeZ / 2;
  for (let i = 0; i < GEN.dungeonCount; i += 1) {
    // Draw every random up front so the stream advances identically whether or
    // not this dungeon turns out to be placeable.
    const cx = 12 + Math.floor(rand() * (world.sizeX - 24));
    const cz = 12 + Math.floor(rand() * (world.sizeZ - 24));
    const floorRoll = rand();
    const secondChest = rand() < 0.6;

    const surface = terrainTopY(world, cx, cz, cfg);
    const minFloor = 7;
    const maxFloor = surface - 7; // keep the ceiling >=3 below the surface
    if (maxFloor < minFloor) continue;
    // Keep dungeons clear of the spawn area so there's no free starter loot.
    if (Math.hypot(cx - centerX, cz - centerZ) < 40) continue;

    const floorY = minFloor + Math.floor(floorRoll * (maxFloor - minFloor + 1));
    buildDungeonRoom(world, cx, cz, floorY, secondChest, write, sink);
  }
}

function placeDungeons(world: VoxelWorld, cfg: TerrainConfig): void {
  buildDungeons(world, true, NOOP_DUNGEON_SINK, cfg);
}

export type DungeonSites = { chestIndices: number[]; spawnerIndices: number[] };

/**
 * Re-derives the voxel indices of every dungeon chest and spawner WITHOUT
 * writing blocks, by replaying buildDungeons' placement math. The engine calls
 * this once after regenerating the world on load to rebuild the session-only
 * dungeon index sets that gate lazy loot fill and spawner activation. It must be
 * passed the same worldType the world was generated with — dungeon depths follow
 * the type's terrain, so the derived indices match what placeDungeons wrote.
 */
export function collectDungeonSites(world: VoxelWorld, worldType: WorldType = "default"): DungeonSites {
  const chestIndices: number[] = [];
  const spawnerIndices: number[] = [];
  buildDungeons(world, false, { chest: (idx) => chestIndices.push(idx), spawner: (idx) => spawnerIndices.push(idx) }, terrainConfigFor(worldType));
  return { chestIndices, spawnerIndices };
}

// ── Villages ────────────────────────────────────────────────────────────────
// Clusters of houses on flat, dry land. Like dungeons, the world's block diff
// can't carry the resident villagers, so the engine re-derives each village's
// center on load (collectVillageSites) and seeds residents there. The same two
// invariants keep build and derive in lockstep: a dedicated PRNG seeded only from
// world.seed, with a fixed number of draws per village; and seed-pure validation
// via terrainTopY (never highestSolidY, which caves/edits could shift).

/** Resident-spawn centers a village contributes (one per placed village). */
type VillageSink = (cx: number, cz: number) => void;
const NOOP_VILLAGE_SINK: VillageSink = () => {};

/** House offsets from the village center — a tidy cross (center + four arms), spaced so 7-wide footprints don't overlap. */
const VILLAGE_HOUSE_OFFSETS: ReadonlyArray<readonly [number, number]> = [
  [0, 0],
  [9, 0],
  [-9, 0],
  [0, 9],
  [0, -9],
  [9, 9],
  [-9, -9],
  [9, -9],
  [-9, 9]
];

/** A PRNG seeded only from the world seed, decoupled from the main gen and dungeon streams. */
function villageRand(seed: number): () => number {
  let t = (seed ^ 0x85ebca6b) >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Seed-pure flatness gate: true when the surface under every house in the village
 * stays within villageFlatnessTolerance of the center's floor. Reads only
 * terrainTopY (no blocks), so build and derive agree on which villages exist.
 */
function villageGroundFlat(world: VoxelWorld, cx: number, cz: number, baseSurface: number, cfg: TerrainConfig): boolean {
  for (let h = 0; h < GEN.villageHouseCount; h += 1) {
    const [ox, oz] = VILLAGE_HOUSE_OFFSETS[h];
    if (!world.inBounds(cx + ox, baseSurface, cz + oz)) return false;
    if (Math.abs(terrainTopY(world, cx + ox, cz + oz, cfg) - baseSurface) > GEN.villageFlatnessTolerance) return false;
  }
  return true;
}

/** Levels a 9×9 pad to `floorY-1` (clearing terrain bumps above, filling just below) and builds a house on it. */
function buildVillageHouse(world: VoxelWorld, cx: number, cz: number, floorY: number): void {
  const pad = 4; // house footprint half-width plus its border
  for (let x = cx - pad; x <= cx + pad; x += 1) {
    for (let z = cz - pad; z <= cz + pad; z += 1) {
      if (!world.inBounds(x, floorY - 1, z)) return;
      world.set(x, floorY - 2, z, BlockId.Dirt);
      world.set(x, floorY - 1, z, BlockId.Grass);
      for (let y = floorY; y <= floorY + 5; y += 1) world.set(x, y, z, BlockId.Air);
    }
  }
  buildHouseShell(world, cx, cz, floorY);
}

function buildVillages(world: VoxelWorld, write: boolean, sink: VillageSink, cfg: TerrainConfig): void {
  const rand = villageRand(world.seed);
  const centerX = world.sizeX / 2;
  const centerZ = world.sizeZ / 2;
  for (let i = 0; i < GEN.villageCount; i += 1) {
    // Draw every random up front so the stream advances identically whether or
    // not this village turns out to be placeable.
    const cx = 20 + Math.floor(rand() * (world.sizeX - 40));
    const cz = 20 + Math.floor(rand() * (world.sizeZ - 40));

    const surface = terrainTopY(world, cx, cz, cfg);
    // Dry, buildable land only (above sea level, not into the sky), clear of the
    // spawn area, and flat enough across the whole footprint — all seed-pure, so
    // the record pass derives the exact same set of villages the write pass built.
    if (surface <= cfg.seaLevel || surface >= world.sizeY - 8) continue;
    if (Math.hypot(cx - centerX, cz - centerZ) < GEN.villageMinSpawnDistance) continue;
    if (!villageGroundFlat(world, cx, cz, surface, cfg)) continue;

    if (write) {
      const floorY = surface + 1;
      for (let h = 0; h < GEN.villageHouseCount; h += 1) {
        const [ox, oz] = VILLAGE_HOUSE_OFFSETS[h];
        buildVillageHouse(world, cx + ox, cz + oz, floorY);
      }
      // Cobblestone paths along the cross arms tie the houses into one settlement.
      for (let d = -9; d <= 9; d += 1) {
        if (world.inBounds(cx + d, floorY - 1, cz)) world.set(cx + d, floorY - 1, cz, BlockId.Cobblestone);
        if (world.inBounds(cx, floorY - 1, cz + d)) world.set(cx, floorY - 1, cz + d, BlockId.Cobblestone);
      }
    }
    sink(cx, cz);
  }
}

function placeVillages(world: VoxelWorld, cfg: TerrainConfig): void {
  buildVillages(world, true, NOOP_VILLAGE_SINK, cfg);
}

export type VillageSites = { centers: Array<{ x: number; z: number }> };

/**
 * Re-derives every village's center WITHOUT writing blocks, by replaying
 * buildVillages' placement math. The engine calls this once after regenerating
 * the world on load to rebuild the session-only village sites that seed resident
 * villagers. Must be passed the same worldType the world was generated with.
 */
export function collectVillageSites(world: VoxelWorld, worldType: WorldType = "default"): VillageSites {
  const centers: Array<{ x: number; z: number }> = [];
  buildVillages(world, false, (x, z) => centers.push({ x, z }), terrainConfigFor(worldType));
  return { centers };
}

