123	 * reflect the edit. Uses the standard remove-then-refill flood, which visits
124	 * only the cells the edit actually changed — cheap for a normal edit, and
125	 * bounded by the shaft depth when a column is capped or opened.
126	 */
127	export function applyEdit(world: VoxelWorld, light: Uint8Array, x: number, y: number, z: number): void {
128	  if (!world.inBounds(x, y, z)) return;
129	  const idx = world.index(x, y, z);
130	  const block = world.blocks[idx] as BlockId;
131	
132	  // Block light: drop the cell, remove what it had lit, then refill from any
133	  // surviving sources plus the new block's own emission.
134	  const oldBlock = light[idx] & BLOCK_MASK;
135	  setChannel(light, idx, 0, false);
136	  const blockRefill = removeChannel(world, light, idx, oldBlock, false);
137	  const emit = emission(block);
138	  if (emit > 0) {
139	    setChannel(light, idx, emit, false);
140	    blockRefill.push(idx);
141	  }
142	  flood(world, light, blockRefill, false);
143	
144	  // Sky light: same dance. The removal honors the sunlight rule, so capping a
145	  // clear column cascades the shadow straight down it.
146	  const oldSky = light[idx] >> SKY_SHIFT;
147	  setChannel(light, idx, 0, true);
148	  const skyRefill = removeChannel(world, light, idx, oldSky, true);
149	  // The open sky above the world is an implicit sunlight source the in-bounds
150	  // remove/refill can't discover. When the edited cell is in the top layer and
151	  // now transmits, reseed its direct sunlight (matching the bake's column pass)
152	  // so reopening a ceiling block re-floods the column instead of underlighting.
153	  if (y === world.sizeY - 1 && !isLightBlocker(block)) {
154	    const seed = MAX_LIGHT - opacity(block);
155	    if (seed > skyLightAt(light, idx)) {
156	      setChannel(light, idx, seed, true);
157	      skyRefill.push(idx);
158	    }
159	  }
160	  flood(world, light, skyRefill, true);
161	}
