163	function bakeSkyLight(world: VoxelWorld, light: Uint8Array): void {
164	  const { sizeX, sizeY, sizeZ } = world;
165	  const layer = sizeX * sizeZ;
166	
167	  // Column pass: sunlight falls straight down for free (no per-step cost) until
168	  // it hits opacity, so an open column reaches the ground at full strength.
169	  for (let z = 0; z < sizeZ; z += 1) {
170	    for (let x = 0; x < sizeX; x += 1) {
171	      let sky = MAX_LIGHT;
172	      let idx = x + z * sizeX + (sizeY - 1) * layer;
173	      for (let y = sizeY - 1; y >= 0; y -= 1, idx -= layer) {
174	        const op = opacity(world.blocks[idx] as BlockId);
175	        sky = op >= OPAQUE ? 0 : Math.max(0, sky - op);
176	        light[idx] = (sky << SKY_SHIFT) | (light[idx] & BLOCK_MASK);
177	      }
178	    }
179	  }
