181	  // Horizontal bleed into shadow. Seed only at brightness gradients (a lit cell
182	  // next to a darker reachable neighbor) so the queue stays bounded instead of
183	  // holding every open-air voxel.
184	  const queue: number[] = [];
185	  for (let idx = 0; idx < light.length; idx += 1) {
186	    const cl = light[idx] >> SKY_SHIFT;
187	    if (cl <= 1) continue;
188	    const y = Math.floor(idx / layer);
189	    const rem = idx - y * layer;
190	    const z = Math.floor(rem / sizeX);
191	    const x = rem - z * sizeX;
192	    if (canLightNeighbor(world, light, x, y, z, cl, true)) queue.push(idx);
193	  }
194	  flood(world, light, queue, true);
195	}
