198	  const queue: number[] = [];
199	  for (let idx = 0; idx < world.blocks.length; idx += 1) {
200	    const emit = emission(world.blocks[idx] as BlockId);
201	    if (emit > 0) {
202	      setChannel(light, idx, emit, false);
203	      queue.push(idx);
204	    }
205	  }
206	  flood(world, light, queue, false);
207	}
208	
209	function canLightNeighbor(world: VoxelWorld, light: Uint8Array, x: number, y: number, z: number, level: number, sky: boolean): boolean {
210	  for (let d = 0; d < NEIGHBORS.length; d += 1) {
211	    const nx = x + NEIGHBORS[d][0];
212	    const ny = y + NEIGHBORS[d][1];
213	    const nz = z + NEIGHBORS[d][2];
214	    if (!world.inBounds(nx, ny, nz)) continue;
215	    const nidx = world.index(nx, ny, nz);
216	    const nb = world.blocks[nidx] as BlockId;
217	    if (isLightBlocker(nb)) continue;
218	    const target = propagated(level, d === DOWN, nb, sky);
219	    if (target > getChannel(light, nidx, sky)) return true;
220	  }
221	  return false;
222	}
