224	/**
225	 * Remove the light a cell used to cast, starting from (sx,sy,sz) which has
226	 * already been zeroed in `light`. Returns the indices of surviving independent
227	 * sources (and adjacent emitters) to refill from. The sky channel honors the
228	 * sunlight rule: a downward neighbor still at full strength was lit by the
229	 * column above, so it is torn down too.
230	 */
231	function removeChannel(world: VoxelWorld, light: Uint8Array, startIdx: number, startLevel: number, sky: boolean): number[] {
232	  const { sizeX, sizeZ } = world;
233	  const layer = sizeX * sizeZ;
234	  const refill: number[] = [];
235	  const idxQueue: number[] = [startIdx];
236	  const levelQueue: number[] = [startLevel];
237	  let head = 0;
238	  while (head < idxQueue.length) {
239	    const idx = idxQueue[head];
240	    const level = levelQueue[head];
241	    head += 1;
242	    const y = Math.floor(idx / layer);
243	    const rem = idx - y * layer;
244	    const z = Math.floor(rem / sizeX);
245	    const x = rem - z * sizeX;
246	    for (let d = 0; d < NEIGHBORS.length; d += 1) {
247	      const nx = x + NEIGHBORS[d][0];
248	      const ny = y + NEIGHBORS[d][1];
249	      const nz = z + NEIGHBORS[d][2];
250	      if (!world.inBounds(nx, ny, nz)) continue;
251	      const nidx = world.index(nx, ny, nz);
252	      const nb = world.blocks[nidx] as BlockId;
253	      if (isLightBlocker(nb)) {
254	        // A blocker holds no flooded light, but a lit emitter (lava) is a fixed
255	        // source the refill must spread from.
256	        if (!sky && emission(nb) > 0) refill.push(nidx);
257	        continue;
258	      }
259	      const nl = getChannel(light, nidx, sky);
260	      // What this cell, at `level`, would have given the neighbor. If the
261	      // neighbor is no brighter than that, it was lit by us — tear it down and
262	      // cascade; otherwise it has an independent source the refill spreads from.
263	      const wouldGive = propagated(level, d === DOWN, nb, sky);
264	      if (nl !== 0 && nl <= wouldGive) {
265	        setChannel(light, nidx, 0, sky);
266	        idxQueue.push(nidx);
267	        levelQueue.push(nl);
268	      } else if (nl > wouldGive && nl > 0) {
269	        refill.push(nidx);
270	      }
271	    }
272	  }
273	  return refill;
274	}
275	
276	/**
277	 * Breadth-first light spread shared by both channels and by the bake and the
278	 * incremental refill. Uses a head pointer rather than Array.shift for O(1)
279	 * dequeue on large frontiers. For the sky channel, light at full strength
280	 * propagating straight down stays at full strength (sunlight).
281	 */
282	function flood(world: VoxelWorld, light: Uint8Array, queue: number[], sky: boolean): void {
283	  const { sizeX, sizeZ } = world;
284	  const layer = sizeX * sizeZ;
285	  let head = 0;
286	  while (head < queue.length) {
287	    const idx = queue[head];
288	    head += 1;
289	    const cl = getChannel(light, idx, sky);
290	    if (cl <= 1) continue;
291	    const y = Math.floor(idx / layer);
292	    const rem = idx - y * layer;
293	    const z = Math.floor(rem / sizeX);
294	    const x = rem - z * sizeX;
295	    for (let d = 0; d < NEIGHBORS.length; d += 1) {
296	      const nx = x + NEIGHBORS[d][0];
297	      const ny = y + NEIGHBORS[d][1];
298	      const nz = z + NEIGHBORS[d][2];
299	      if (!world.inBounds(nx, ny, nz)) continue;
300	      const nidx = world.index(nx, ny, nz);
301	      const nb = world.blocks[nidx] as BlockId;
302	      if (isLightBlocker(nb)) continue;
303	      const target = propagated(cl, d === DOWN, nb, sky);
304	      if (target > getChannel(light, nidx, sky)) {
305	        setChannel(light, nidx, target, sky);
306	        queue.push(nidx);
307	      }
308	    }
309	  }
310	}
