1	import * as THREE from "three";
2	import { BlockId, collidesAt, doorBlock, doorFacingFromYaw, doorState, isDoorBlock, voxelRaycast } from "@/lib/world";
3	import { BARE_HAND_MINE_POWER, CHEST_SLOTS, EYE_HEIGHT, MINE_REACH, MINING_RATE, PLAYER_HALF_WIDTH, PLAYER_HEIGHT } from "@/lib/game/config";
4	import { BREAK_HARDNESS, createEmptySlot, rollBlockDrops } from "@/lib/game/items";
5	import { adjustSlotCount, consumeToolDurability, tryInsertSlots } from "@/lib/game/inventory";
6	import { canEditBlocks, freeBuild } from "@/lib/game/gameModes";
7	import type { EmitGameEvent, FrameInput, GameState } from "../state";
8	import { efficiencyMultiplier, fortuneLevel } from "@/lib/game/enchantments";
9	import { fillDungeonChestIfUnlooted } from "./dungeon";
10	import { lookDirection } from "./playerMotion";
11	import { awardXp, xpForBlock } from "./xp";
12	import { hasteMultiplier } from "./statusEffects";
13	import type { InventorySlot } from "@/lib/game/types";
14	
15	const scratchEye = new THREE.Vector3();
16	const scratchDir = new THREE.Vector3();
17	
18	function eyePosition(state: GameState, out: THREE.Vector3): THREE.Vector3 {
19	  const { position } = state.player;
20	  return out.set(position.x, position.y + EYE_HEIGHT, position.z);
21	}
22	
23	export function selectedTool(state: GameState): InventorySlot | null {
24	  const slot = state.inventory[state.selectedSlot];
25	  return slot?.kind === "tool" && slot.count > 0 ? slot : null;
26	}
27	
28	export function canMineBlock(block: BlockId, toolTier: number): boolean {
29	  if (block === BlockId.Stone || block === BlockId.Cobblestone || block === BlockId.Brick) return toolTier >= 1;
30	  if (block === BlockId.CoalOre) return toolTier >= 1;
31	  if (block === BlockId.SliverOre) return toolTier >= 2;
32	  if (block === BlockId.RubyOre) return toolTier >= 3;
33	  if (block === BlockId.GoldOre) return toolTier >= 3;
34	  if (block === BlockId.SapphireOre) return toolTier >= 4;
35	  if (block === BlockId.DiamondOre) return toolTier >= 4;
36	  return true;
37	}
38	
39	export function miningSpeed(tool: InventorySlot | null): number {
40	  return (tool?.minePower ?? BARE_HAND_MINE_POWER) * efficiencyMultiplier(tool);
41	}
42	
43	export function resetMining(state: GameState): void {
44	  state.mining.targetKey = "";
45	  state.mining.progress = 0;
46	}
47	
48	function addBlockDrop(state: GameState, block: BlockId, rng: () => number, tool: InventorySlot | null): void {
49	  for (const drop of rollBlockDrops(block, rng, fortuneLevel(tool))) {
50	    state.inventory = adjustSlotCount(state.inventory, drop.itemId, drop.count) ?? state.inventory;
51	  }
52	}
53	
54	/**
55	 * Empties a broken chest into the inventory. Returns true if the break may
56	 * proceed (the chest was empty, or its contents all fit), false to refuse it
57	 * (no room — the chest is left intact). On success the container entry is
58	 * removed and a pickedUp toast announces what was retrieved.
59	 */
60	function spillChestOnBreak(state: GameState, idx: number, emit: EmitGameEvent): boolean {
61	  // Breaking an unopened dungeon chest still pays out its loot.
62	  fillDungeonChestIfUnlooted(state, idx);
63	  const container = state.containers.get(idx);
64	  const items = container?.filter((slot) => slot.id && slot.count > 0) ?? [];
65	  if (items.length > 0) {
66	    const merged = tryInsertSlots(state.inventory, items);
67	    if (!merged) {
68	      emit({ type: "breakBlocked", reason: "containerFull" });
69	      return false;
70	    }
71	    state.inventory = merged;
72	    const picked = new Map<string, number>();
73	    for (const slot of items) picked.set(slot.id!, (picked.get(slot.id!) ?? 0) + slot.count);
74	    emit({ type: "pickedUp", items: [...picked].map(([itemId, count]) => ({ itemId, count })) });
75	  }
76	  state.containers.delete(idx);
77	  return true;
78	}
79	
80	/** Advances mining progress while the mouse is held; breaks the block at full progress. */
81	export function tickMining(state: GameState, input: FrameInput, dt: number, emit: EmitGameEvent, rng: () => number): void {
82	  if (!input.leftMouseHeld) {
83	    // Releasing the button abandons progress (matching the crack overlay).
84	    if (state.mining.progress > 0) resetMining(state);
85	    return;
86	  }
87	  if (state.inventoryOpen || state.isDead || !input.pointerLocked) return;
88	  // Adventure and Spectator can't break terrain.
89	  if (!canEditBlocks(state.gameMode)) {
90	    resetMining(state);
91	    return;
92	  }
93	
94	  const { world, mining } = state;
95	  const origin = eyePosition(state, scratchEye);
96	  const direction = lookDirection(state.player.yaw, state.player.pitch, scratchDir);
97	  const result = voxelRaycast(world, origin, direction, MINE_REACH);
98	  if (!result) {
99	    resetMining(state);
100	    return;
101	  }
102	
103	  const bx = result.hit.x;
104	  const by = result.hit.y;
105	  const bz = result.hit.z;
106	  const targetBlock = world.get(bx, by, bz);
107	  const tool = selectedTool(state);
108	  const tier = tool?.mineTier ?? 0;
109	  // Creative breaks anything (bar bedrock) instantly, regardless of tool tier.
110	  const creative = freeBuild(state.gameMode);
111	
112	  if (targetBlock === BlockId.Bedrock || targetBlock === BlockId.Air || (!creative && !canMineBlock(targetBlock as BlockId, tier))) {
113	    resetMining(state);
114	    return;
115	  }
116	
117	  const key = `${bx},${by},${bz}`;
118	  if (mining.targetKey !== key) {
119	    mining.targetKey = key;
120	    mining.progress = 0;
121	  }
122	
123	  if (!creative) {
124	    const hardness = BREAK_HARDNESS[targetBlock as BlockId] ?? 2;
125	    mining.progress += dt * miningSpeed(tool) * MINING_RATE * hasteMultiplier(state);
126	    if (mining.progress < hardness) return;
127	  }
128	
129	  // Breaking a chest empties it into the inventory first; if it does not all
130	  // fit, refuse the break so nothing is lost (the chest stays intact). Creative
131	  // breaks for free — the chest and its contents just vanish (no spill, no refusal).
132	  const chestIndex = targetBlock === BlockId.Chest ? world.index(bx, by, bz) : null;
133	  if (chestIndex !== null) {
134	    if (creative) state.containers.delete(chestIndex);
135	    else if (!spillChestOnBreak(state, chestIndex, emit)) {
136	      resetMining(state);
137	      return;
138	    }
139	  }
140	
141	  if (isDoorBlock(targetBlock)) {
142	    const door = doorState(targetBlock)!;
143	    const other = doorState(world.get(bx, door.upper ? by - 1 : by + 1, bz));
144	    state.blockChanges.set(bx, by, bz, BlockId.Air);
145	    if (other && other.upper !== door.upper) {
