if (isDoorBlock(targetBlock)) {
  const door = doorState(targetBlock)!;
  const other = doorState(world.get(bx, door.upper ? by - 1 : by + 1, bz));
  state.blockChanges.set(bx, by, bz, BlockId.Air);
